export default {
  async fetch(request, env) {
    const url = new URL(request.url);
    const accept = request.headers.get('Accept') || '';
    const starScope = request.headers.get('X-Star-Request');

    // Content negotiation
    if (accept.includes('text/markdown')) {
      url.pathname = `/md${url.pathname}index.md`;
    } else if (accept.includes('application/json')) {
      url.pathname = `/api${url.pathname.replace(/\/$/, '')}.json`;
    } else if (starScope === 'content') {
      url.pathname = `${url.pathname}_fragment.html`;
    }

    return env.ASSETS.fetch(new Request(url, request));
  },
};
